function validate([pid, ppid, kill]) {
  const n = pid.length;
  if (n < 1 || n > 50000) return 'There are 1 to 5 * 10^4 processes.';
  if (ppid.length !== n) return 'pid and ppid must have the same length.';
  if (pid.some(id => id < 1 || id > 50000)) return 'Each pid[i] is between 1 and 5 * 10^4.';
  if (ppid.some(id => id < 0 || id > 50000)) return 'Each ppid[i] is between 0 and 5 * 10^4.';
  const ids = new Set(pid);
  if (ids.size !== n) return 'Process IDs in pid must be unique.';
  if (ppid.filter(id => id === 0).length !== 1) return 'Exactly one process (the root) has ppid 0.';
  if (ppid.some(id => id !== 0 && !ids.has(id))) return 'Every nonzero ppid must be an ID from pid.';
  // Walk down from the root: every process must be reached, otherwise some parents form a cycle.
  const children = new Map();
  for (let i = 0; i < n; i++) {
    if (!children.has(ppid[i])) children.set(ppid[i], []);
    children.get(ppid[i]).push(pid[i]);
  }
  const queue = [0];
  for (let head = 0; head < queue.length; head++) for (const child of children.get(queue[head]) || []) queue.push(child);
  if (queue.length - 1 !== n) return 'The processes must form one tree, without cycles.';
  if (!ids.has(kill)) return 'kill must be one of the IDs in pid.';
  return null;
}

