function killProcess(pid, ppid, kill) {
  // A process dies exactly when kill is on its path up to the root (itself included).
  const parentOf = new Map();
  pid.forEach((id, i) => parentOf.set(id, ppid[i]));
  const result = [];
  for (const id of pid) {
    let walker = id;
    while (walker !== 0 && walker !== kill) walker = parentOf.get(walker);
    if (walker === kill) result.push(id);
  }
  return result;
}

