function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 1900 + pick(101) : 1 + pick(10);
  const span = size === 'large' || rand() < 0.3 ? 50000 : 3 * n;
  // Distinct IDs: the first one becomes the root.
  const used = new Set();
  const ids = [];
  while (ids.length < n) {
    const id = 1 + pick(span);
    if (!used.has(id)) { used.add(id); ids.push(id); }
  }
  const deep = rand() < 0.4;
  const parent = [0];
  for (let k = 1; k < n; k++) parent.push(ids[deep ? Math.max(0, k - 1 - pick(3)) : pick(k)]);
  // List the processes in a random order so the root is not always first.
  const order = ids.map((_, k) => k);
  for (let k = n - 1; k > 0; k--) { const j = pick(k + 1); [order[k], order[j]] = [order[j], order[k]]; }
  return [order.map(k => ids[k]), order.map(k => parent[k]), ids[pick(n)]];
}
